import React, { useState, useEffect } from "react";
import axios from "axios";
import MessageList from "./MessageList";
import InputForm from "./InputForm";

const API_URL = "http://localhost:5000/messages";
const DEEPAI_API_KEY = "your_deepai_api_key"; // Replace with your DeepAI API key

const Chat = () => {
  const [messages, setMessages] = useState([]);

  useEffect(() => {
    axios.get(API_URL).then((response) => {
      setMessages(response.data);
    });
  }, []);

  const sendMessage = async (text) => {
    const userMessage = { text, sender: "user" };
    setMessages([...messages, userMessage]);

    // Save user message to json-server
    await axios.post(API_URL, userMessage);

    // Fetch AI response
    const response = await axios.post(
      "https://api.deepai.org/api/text-generator",
      { text },
      { headers: { "Api-Key": DEEPAI_API_KEY } }
    );

    const aiMessage = { text: response.data.output, sender: "ai" };
    setMessages([...messages, userMessage, aiMessage]);

    // Save AI message to json-server
    await axios.post(API_URL, aiMessage);
  };

  return (
    <div className="chat-container">
      <MessageList messages={messages} />
      <InputForm sendMessage={sendMessage} />
    </div>
  );
};

export default Chat;
